package vn.codegym;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/discount") public class DiscountServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("text/html;charset=UTF-8");s.getWriter().print("<form method='post'><input name='description' placeholder='Mô tả sản phẩm'><input type='number' step='0.01' name='price' placeholder='Giá' required><input type='number' step='0.01' name='percent' placeholder='% giảm' required><button>Tính</button></form>");}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("text/html;charset=UTF-8");double price=Double.parseDouble(r.getParameter("price")),percent=Double.parseDouble(r.getParameter("percent")),amount=price*percent/100;s.getWriter().printf("<h1>%s</h1><p>Giảm: %,.2f</p><p>Giá sau giảm: %,.2f</p>",r.getParameter("description"),amount,price-amount);}}
